import React from 'react';
import './ProgressCircle.css';

type ProgressCircleProps = {
  progress: number;
  size?: number;
  strokeWidth?: number;
  variant?: 'primary' | 'secondary' | 'success';
  showPercentage?: boolean;
};

const ProgressCircle: React.FC<ProgressCircleProps> = ({
  progress,
  size = 120,
  strokeWidth = 10,
  variant = 'primary',
  showPercentage = true,
}) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  const getVariantClass = () => {
    switch (variant) {
      case 'secondary':
        return 'progress-circle--secondary';
      case 'success':
        return 'progress-circle--success';
      default:
        return 'progress-circle--primary';
    }
  };

  return (
    <div className={`progress-circle ${getVariantClass()}`} style={{ width: size, height: size }}>
      <svg className="progress-circle__svg" width={size} height={size}>
        <circle
          className="progress-circle__bg"
          cx={size / 2}
          cy={size / 2}
          r={radius}
          strokeWidth={strokeWidth}
        />
        <circle
          className="progress-circle__fill"
          cx={size / 2}
          cy={size / 2}
          r={radius}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          transform={`rotate(-90 ${size / 2} ${size / 2})`}
        />
      </svg>
      {showPercentage && (
        <div className="progress-circle__text">
          {Math.round(progress)}%
        </div>
      )}
    </div>
  );
};

export default ProgressCircle;

src/components/progress/ProgressSteps.ts:
import React, { useState } from 'react';
import './ProgressSteps.css';

type Step = {
  id: number;
  title: string;
  description: string;
  completed: boolean;
};

type ProgressStepsProps = {
  steps: Step[];
  variant?: 'default' | 'compact' | 'vertical';
  onStepChange?: (stepId: number) => void;
};

const ProgressSteps: React.FC<ProgressStepsProps> = ({
  steps,
  variant = 'default',
  onStepChange,
}) => {
  const [currentStep, setCurrentStep] = useState<number>(0);

  const handleStepClick = (stepId: number) => {
    if (onStepChange) {
      onStepChange(stepId);
    }
    setCurrentStep(stepId);
  };

  const getVariantClass = () => {
    switch (variant) {
      case 'compact':
        return 'progress-steps-compact';
      case 'vertical':
        return 'progress-steps-vertical';
      default:
        return 'progress-steps-default';
    }
  };

  return (
    <div className={`progress-steps ${getVariantClass()}`}>
      {steps.map((step, index) => (
        <div
          key={step.id}
          className={`progress-step ${currentStep >= index ? 'active' : ''} ${
            step.completed ? 'completed' : ''
          }`}
          onClick={() => handleStepClick(index)}
        >
          <div className="step-indicator">
            {step.completed ? (
              <span className="step-icon">✓</span>
            ) : (
              <span className="step-number">{index + 1}</span>
            )}
          </div>
          <div className="step-content">
            <h4 className="step-title">{step.title}</h4>
            {variant !== 'compact' && (
              <p className="step-description">{step.description}</p>
            )}
          </div>
          {index < steps.length - 1 && (
            <div className="step-connector"></div>
          )}
        </div>
      ))}
    </div>
  );
};

export default ProgressSteps;

